import sys
sys.setrecursionlimit(10**6)

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    if n == 1:
        print("1")
        return

    adj = [[] for _ in range(n + 1)]
    idx = 1
    for _ in range(n - 1):
        u = int(data[idx])
        v = int(data[idx + 1])
        idx += 2
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (n + 1)
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    sz = [1] * (n + 1)
    for u in reversed(order):
        p = parent[u]
        if p != 0:
            sz[p] += sz[u]

    def get_max_component(u):
        max_c = n - sz[u]
        for v in adj[u]:
            if v != parent[u]:
                if sz[v] > max_c:
                    max_c = sz[v]
        return max_c

    threshold = n // 2
    ans = [0] * (n + 1)

    for u in range(1, n + 1):
        max_c = get_max_component(u)
        if max_c <= threshold:
            ans[u] = 1
            continue

        heavy_child = None
        for v in adj[u]:
            if v != parent[u] and sz[v] > threshold:
                heavy_child = v
                break

        if heavy_child is None:
            if n - sz[u] > threshold:
                pass
            else:
                ans[u] = 1
            continue

        if n - sz[u] > threshold:
            continue

        if len(adj[heavy_child]) == 1:
            if heavy_child == 1:
                continue
            p_heavy = parent[heavy_child]
            if p_heavy != u:
                continue
            if len(adj[u]) > 1:
                ans[u] = 1
            else:
                continue
        else:
            if len(adj[u]) > 1:
                ans[u = 1]
            else:
                continue

    print(" ".join(str(ans[i]) for i in range(1, n + 1)))

if __name__ == "__main__":
    main()
